:root {
  --bg: #f4f7fb;
  --card: #ffffff;
  --text: #172033;
  --muted: #687286;
  --primary: #2563eb;
  --primary-dark: #1d4ed8;
  --secondary: #eef2ff;
  --border: #dce3ef;
  --danger: #dc2626;
  --danger-dark: #b91c1c;
  --success-bg: #dcfce7;
  --success-text: #166534;
  --error-bg: #fee2e2;
  --error-text: #991b1b;
  --shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  background: var(--bg);
  color: var(--text);
}

a {
  color: inherit;
}

.topbar {
  background: var(--card);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.topbar-inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 14px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand {
  text-decoration: none;
  font-weight: 800;
  color: var(--primary);
  font-size: 20px;
}

.nav {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.nav a {
  text-decoration: none;
  font-weight: 600;
  color: var(--text);
}

.nav a:hover {
  color: var(--primary);
}

.inline-form {
  display: inline;
  margin: 0;
}

.link-button {
  border: 0;
  background: none;
  color: var(--danger);
  font-weight: 700;
  cursor: pointer;
  font-size: 16px;
  padding: 0;
}

.container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 28px 18px 60px;
}

.container.narrow {
  max-width: 680px;
}

.page-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.page-title h1 {
  margin: 0 0 6px;
  font-size: 34px;
}

.page-title p {
  margin: 0;
  color: var(--muted);
}

.card,
.task-card,
.login-card {
  background: var(--card);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: 18px;
}

.card {
  padding: 22px;
  margin-bottom: 22px;
}

.card h1,
.card h2 {
  margin-top: 0;
}

.login-page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 18px;
  background: linear-gradient(135deg, #dbeafe, #f4f7fb);
}

.login-card {
  width: 100%;
  max-width: 420px;
  padding: 30px;
}

.login-card h1 {
  margin: 0 0 8px;
  color: var(--primary);
}

.muted {
  color: var(--muted);
}

.default-login {
  margin-top: 18px;
  padding: 12px;
  background: #f8fafc;
  border: 1px dashed var(--border);
  border-radius: 12px;
  color: var(--muted);
  line-height: 1.5;
}

.form,
.grid-form {
  display: grid;
  gap: 16px;
}

.grid-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

label {
  display: grid;
  gap: 7px;
  font-weight: 700;
  color: var(--text);
}

input,
select,
textarea {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px 13px;
  font-size: 16px;
  font-family: inherit;
  background: #fff;
  color: var(--text);
}

textarea {
  resize: vertical;
}

input:focus,
select:focus,
textarea:focus {
  outline: 3px solid rgba(37, 99, 235, 0.18);
  border-color: var(--primary);
}

.full-row {
  grid-column: 1 / -1;
}

.button,
.small-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  text-decoration: none;
  cursor: pointer;
  font-weight: 800;
  border-radius: 12px;
  background: var(--primary);
  color: #fff;
}

.button {
  padding: 12px 18px;
  font-size: 16px;
}

.button:hover {
  background: var(--primary-dark);
}

.button.full {
  width: 100%;
}

.button.secondary,
.small-button {
  background: var(--secondary);
  color: var(--primary);
}

.button.secondary:hover,
.small-button:hover {
  background: #dbe4ff;
}

.small-button {
  padding: 8px 10px;
  font-size: 14px;
}

.small-button.danger {
  background: #fee2e2;
  color: var(--danger);
}

.small-button.danger:hover {
  background: var(--danger);
  color: #fff;
}

.alert {
  padding: 14px 16px;
  border-radius: 14px;
  margin-bottom: 18px;
  font-weight: 700;
}

.alert.success {
  background: var(--success-bg);
  color: var(--success-text);
}

.alert.error {
  background: var(--error-bg);
  color: var(--error-text);
}

.tasks {
  display: grid;
  gap: 18px;
}

.task-card {
  padding: 20px;
  border-left: 8px solid var(--border);
}

.task-card.status-pendente {
  border-left-color: #f59e0b;
}

.task-card.status-em-andamento {
  border-left-color: #2563eb;
}

.task-card.status-concluída {
  border-left-color: #22c55e;
}

.task-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.task-header h2 {
  margin: 0 0 8px;
}

.badge {
  display: inline-flex;
  padding: 6px 10px;
  background: #f1f5f9;
  color: var(--muted);
  border-radius: 999px;
  font-weight: 800;
  font-size: 13px;
  text-transform: uppercase;
}

.description {
  color: var(--text);
  line-height: 1.5;
  white-space: pre-wrap;
}

.task-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
  color: var(--muted);
  margin: 14px 0;
  font-size: 14px;
}

.status-form {
  display: flex;
  gap: 12px;
  align-items: end;
  flex-wrap: wrap;
  border-top: 1px solid var(--border);
  padding-top: 14px;
}

.status-form label {
  min-width: 220px;
}

.actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

.actions form {
  margin: 0;
}

.empty {
  padding: 30px;
  background: var(--card);
  border: 1px dashed var(--border);
  border-radius: 18px;
  text-align: center;
  color: var(--muted);
  font-weight: 700;
}

.form-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  border-bottom: 1px solid var(--border);
  padding: 12px;
  text-align: left;
}

th {
  color: var(--muted);
  font-size: 14px;
  text-transform: uppercase;
}

td form {
  margin: 0;
}

@media (max-width: 760px) {
  .topbar-inner {
    align-items: flex-start;
    flex-direction: column;
  }

  .nav {
    gap: 10px 14px;
  }

  .page-title h1 {
    font-size: 28px;
  }

  .grid-form {
    grid-template-columns: 1fr;
  }

  .task-header {
    flex-direction: column;
  }

  .actions {
    width: 100%;
  }

  .status-form {
    display: grid;
  }

  .status-form label {
    min-width: 0;
  }

  .button,
  .small-button {
    width: 100%;
  }
}
